const zcodeTestSecret = "test-secret-for-go-port"

// stubZcodeSecret routes every enc:v1 operation at the test secret.
func stubZcodeSecret(t *testing.T) {
	t.Helper()
	t.Setenv("ZCODE_CREDENTIAL_SECRET", zcodeTestSecret)
}

func TestZcodeCryptoVector(t *testing.T) {
	stubZcodeSecret(t)
	// Generated by zcode-switcher's src/zcodeCrypto.js with the same secret:
	//   encrypt('hello-token-12345', 'test-secret-for-go-port')
	const vector = "enc:v1:8WriUHhvVhBa3Wfg.Xej9dOaZn7x8KkC7gDtJVw.ZG5Tyi4LXTwU5704DQJyEWc"
	plain, err := zcodeDecrypt(vector, zcodeCredentialSecret())
	if err != nil || plain != "hello-token-12345" {
		t.Fatalf("decrypt js vector: %q %v", plain, err)
	}
	// Plaintext passes through untouched.
	if got, _ := zcodeDecrypt("plain-text", zcodeCredentialSecret()); got != "plain-text" {
		t.Fatalf("plaintext passthrough: %q", got)
	}
	// Wrong secret must fail, not corrupt.
	if _, err := zcodeDecrypt(vector, "other-secret"); err == nil {
		t.Fatal("decrypt with a wrong secret must fail")
	}
	// Go encrypt must round-trip through the same decrypt.
	sealed, err := zcodeEncrypt("round-trip-凭证", zcodeCredentialSecret())
	if err != nil {
		t.Fatal(err)
	}
	if !isZcodeEncrypted(sealed) {
		t.Fatalf("encrypt must emit the enc:v1 prefix: %q", sealed)
	}
	if back, err := zcodeDecrypt(sealed, zcodeCredentialSecret()); err != nil || back != "round-trip-凭证" {
		t.Fatalf("round trip: %q %v", back, err)
	}
}

// makeJWT builds an unsigned JWT carrying the payload (fingerprint only reads
// the payload).
func makeJWT(payload map[string]any) string {
	raw, _ := json.Marshal(payload)
	return "eyJhbGciOiJIUzI1NiJ9." + base64.RawURLEncoding.EncodeToString(raw) + ".sig"
}

func TestDecodeJWTPayload(t *testing.T) {
	payload := decodeJWTPayload(makeJWT(map[string]any{"user_id": "u123456789"}))
	if payload["user_id"] != "u123456789" {
		t.Fatalf("payload: %v", payload)
	}
	if decodeJWTPayload("not-a-jwt") != nil {
		t.Fatal("malformed jwt must yield nil")
	}
}

func TestDjb2HexMatchesJS(t *testing.T) {
	// node -e: h=5381; for (c of 'a@b.com') h=((h*33)^c.charCodeAt(0))>>>0;
	// console.log(h.toString(16))
	if got := djb2Hex("a@b.com"); got != "c7a15ec9" {
		t.Fatalf("djb2Hex: %q", got)
	}
}

func TestZcodeFingerprint(t *testing.T) {
	stubZcodeSecret(t)
	userInfo, err := zcodeEncrypt(`{"email":"a@b.com","name":"Alice","user_id":"u123456789"}`, zcodeCredentialSecret())
	if err != nil {
		t.Fatal(err)
	}
	credentials := map[string]any{
		"oauth:active_provider":  "zai",
		"oauth:zai:user_info":    userInfo,
		"oauth:zai:access_token": "ignored",
	}
	config := map[string]any{
		"provider": map[string]any{
			"builtin:zai": map[string]any{
				"enabled": true,
				"options": map[string]any{"apiKey": makeJWT(map[string]any{
					"user_id":     "u123456789",
					"customer_id": "c-1",
					"user_key":    "k-1",
				})},
			},
		},
	}
	fp := zcodeFingerprintFrom(credentials, config)
	if fp == nil {
		t.Fatal("fingerprint missing")
	}
	if fp.UserID != "u123456789" || fp.ShortID != "u1234567" {
		t.Fatalf("fingerprint ids: %+v", fp)
	}
	if fp.Email != "a@b.com" || fp.Name != "Alice" || fp.Provider != "builtin:zai" {
		t.Fatalf("fingerprint identity: %+v", fp)
	}
	if fp.ID != "em-"+djb2Hex("a@b.com") {
		t.Fatalf("email dedupe id: %q", fp.ID)
	}
	if fp.CustomerID != "c-1" || fp.UserKey != "k-1" {
		t.Fatalf("jwt extras: %+v", fp)
	}

	// No email: the id falls back to the shortId.
	fp = zcodeFingerprintFrom(nil, config)
	if fp == nil || fp.ID != "u1234567" || fp.Email != "" {
		t.Fatalf("no-email fingerprint: %+v", fp)
	}
	// Non-string user_id must not become an account id (bigmodel integer ids).
	bad := map[string]any{"provider": map[string]any{"p": map[string]any{
		"enabled": true,
		"options": map[string]any{"apiKey": makeJWT(map[string]any{"user_id": 12345})},
	}}}
	if fp := zcodeFingerprintFrom(nil, bad); fp != nil {
		t.Fatalf("integer user_id must be rejected: %+v", fp)
	}
}

func TestZcodeCandidateTokens(t *testing.T) {
	stubZcodeSecret(t)
	jwtToken, _ := zcodeEncrypt("jwt-token-value-1234567890", zcodeCredentialSecret())
	zaiToken, _ := zcodeEncrypt("zai-token-value-12345678901", zcodeCredentialSecret())
	credentials := map[string]any{
		"zcodejwttoken":          jwtToken,
		"oauth:zai:access_token": zaiToken,
	}
	config := map[string]any{
		"provider": map[string]any{
			"builtin:zai": map[string]any{"options": map[string]any{"apiKey": "config-api-key-1234567890123"}},
			"builtin:bad": map[string]any{"options": map[string]any{"apiKey": "short"}},
		},
	}
	tokens := zcodeCandidateTokens(credentials, config)
	want := []string{"jwt-token-value-1234567890", "zai-token-value-12345678901", "config-api-key-1234567890123"}
	if fmt.Sprint(tokens) != fmt.Sprint(want) {
		t.Fatalf("tokens: %v", tokens)
	}
	// Undecryptable values yield no token instead of failing the account.
	bad := map[string]any{"zcodejwttoken": "enc:v1:AAAA.BBBB.CCCC"}
	if tokens := zcodeCandidateTokens(bad, nil); len(tokens) != 0 {
		t.Fatalf("bad enc must be skipped: %v", tokens)
	}
}

// setupZcodeFixture pools two zcode accounts (accounts[0] occupying the
// slot, accounts[1] the backup) with snapshots under a temp ZCODE_HOME. The
// same *Account pointers are returned: enc:v1 fields are randomly nonced, so
// re-generating a fixture would not byte-match the stored snapshot.
func setupZcodeFixture(t *testing.T) (*Manager, string, []*Account) {
	t.Helper()
	stubZcodeSecret(t)
	m := newTestManager(t)
	home := t.TempDir()
	t.Setenv("ZCODE_HOME", home)
	accounts := zcodeFixtureAccounts(t)
	for _, acc := range accounts {
		if err := m.saveAccount("zcode", acc); err != nil {
			t.Fatal(err)
		}
	}
	writeZcodeSlotFiles(t, home, &zcodeSlot{Credentials: accounts[0].Credentials, Config: accounts[0].Config})
	// No desktop app or real credential validation in tests.
	restore := zcodeDesktopRunning
	zcodeDesktopRunning = func() bool { return false }
	restoreValidation := zcodeValidateLogin
	zcodeValidateLogin = func(context.Context, *Account) error { return nil }
	t.Cleanup(func() {
		zcodeDesktopRunning = restore
		zcodeValidateLogin = restoreValidation
	})
	return m, home, accounts
}

func zcodeFixtureSlot(t *testing.T, id string) *zcodeSlot {
	t.Helper()
	userInfo, err := zcodeEncrypt(`{"email":"`+id+`@example.com","user_id":"uid-`+id+`"}`, zcodeCredentialSecret())
	if err != nil {
		t.Fatal(err)
	}
	token, err := zcodeEncrypt("token-"+id+"-1234567890123456", zcodeCredentialSecret())
	if err != nil {
		t.Fatal(err)
	}
	credRaw, _ := json.Marshal(map[string]any{
		"oauth:active_provider":  "zai",
		"oauth:zai:user_info":    userInfo,
		"oauth:zai:access_token": token,
	})
	cfgRaw, _ := json.Marshal(map[string]any{
		"provider": map[string]any{
			"builtin:zai": map[string]any{
				"enabled": true,
				"options": map[string]any{"apiKey": makeJWT(map[string]any{"user_id": "uid-" + id + "-000000000000000"})},
			},
		},
	})
	return &zcodeSlot{Credentials: string(credRaw), Config: string(cfgRaw)}
}

func zcodeFixtureAccounts(t *testing.T) []*Account {
	t.Helper()
	var out []*Account
	for _, id := range []string{"za", "zb"} {
		slot := zcodeFixtureSlot(t, id)
		fp := zcodeFingerprintFrom(parseJSONObject(slot.Credentials), parseJSONObject(slot.Config))
		if fp == nil {
			t.Fatalf("fixture fingerprint missing for %s", id)
		}
		out = append(out, &Account{
			ID: fp.ID, Label: "账号" + id, UserID: fp.UserID, Email: fp.Email,
			Provider: fp.Provider, Credentials: slot.Credentials, Config: slot.Config,
			Status: StatusActive,
		})
	}
	return out
}

func writeZcodeSlotFiles(t *testing.T, home string, slot *zcodeSlot) {
	t.Helper()
	dir := filepath.Join(home, "v2")
	if err := os.MkdirAll(dir, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "credentials.json"), []byte(slot.Credentials), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "config.json"), []byte(slot.Config), 0o600); err != nil {
		t.Fatal(err)
	}
}

func readZcodeSlotFiles(t *testing.T, home string) *zcodeSlot {
	t.Helper()
	cred, err := os.ReadFile(filepath.Join(home, "v2", "credentials.json"))
	if err != nil {
		return nil
	}
	cfg, err := os.ReadFile(filepath.Join(home, "v2", "config.json"))
	if err != nil {
		return nil
	}
	return &zcodeSlot{Credentials: string(cred), Config: string(cfg)}
}

func TestZcodeCaptureAndActiveID(t *testing.T) {
	m, _, accounts := setupZcodeFixture(t)
	if got := m.activeID("zcode"); got == "" {
		t.Fatal("active id must match the slot account")
	} else if got != accounts[0].ID {
		t.Fatalf("active id: %q want %q", got, accounts[0].ID)
	}
	// Capturing the current login state merges into the same account.
	_, created, err := m.CaptureCurrent(context.Background(), "zcode")
	if err != nil {
		t.Fatal(err)
	}
	if created {
		t.Fatal("capture of the already-pooled account must merge, not create")
	}
}

func TestZcodeSwitchSuccess(t *testing.T) {
	m, home, targets := setupZcodeFixture(t)
	sessions := &fakeSM{live: map[string]string{"sess-1": "/tmp/proj"}}
	if err := m.Switch(context.Background(), "zcode", targets[1].ID, "manual", sessions, nil); err != nil {
		t.Fatalf("switch: %v", err)
	}
	slot := readZcodeSlotFiles(t, home)
	if slot == nil || slot.Credentials != targets[1].Credentials || slot.Config != targets[1].Config {
		t.Fatalf("slot not switched: %+v", slot)
	}
	if got := m.activeID("zcode"); got != targets[1].ID {
		t.Fatalf("active id after switch: %q", got)
	}
	if len(sessions.reattached) != 1 || sessions.reattached[0] != "sess-1" {
		t.Fatalf("reattached: %v", sessions.reattached)
	}
	history := m.History("zcode", 10)
	if len(history) != 1 || !history[0].OK || history[0].To != targets[1].ID {
		t.Fatalf("history: %+v", history)
	}
}

func TestZcodeSwitchRollbackOnReattachFailure(t *testing.T) {
	m, home, targets := setupZcodeFixture(t)
	sessions := &fakeSM{live: map[string]string{"sess-1": "/tmp"}, failOn: map[string]bool{"sess-1": true}}
	err := m.Switch(context.Background(), "zcode", targets[1].ID, "manual", sessions, nil)
	if err == nil || !strings.Contains(err.Error(), "已恢复原账号") {
		t.Fatalf("expected rollback error, got %v", err)
	}
	slot := readZcodeSlotFiles(t, home)
	if slot == nil || slot.Credentials != targets[0].Credentials {
		t.Fatal("slot must be restored to the outgoing account")
	}
	if got := m.activeID("zcode"); got != targets[0].ID {
		t.Fatalf("active id after rollback: %q", got)
	}
}

func TestZcodeSwitchReadsBackDriftedSlot(t *testing.T) {
	m, home, targets := setupZcodeFixture(t)
	// The desktop app rewrote the slot after the snapshot was taken.
	drifted := zcodeFixtureSlot(t, "za-drifted")
	writeZcodeSlotFiles(t, home, drifted)
	// activeID no longer matches (drifted fingerprint) — switch still works,
	// keyed off the slot content rather than the pool.
	if err := m.Switch(context.Background(), "zcode", targets[1].ID, "manual", nil, nil); err != nil {
		t.Fatalf("switch: %v", err)
	}
	slot := readZcodeSlotFiles(t, home)
	if slot.Credentials != targets[1].Credentials {
		t.Fatal("slot not switched after drift")
	}
}

