func TestZcodeImport(t *testing.T) {
	stubZcodeSecret(t)
	m := newTestManager(t)
	source := t.TempDir()
	dir := filepath.Join(source, "accounts-zcode")
	if err := os.MkdirAll(dir, 0o700); err != nil {
		t.Fatal(err)
	}
	slot := zcodeFixtureSlot(t, "imp")
	snapRaw, _ := json.Marshal(map[string]string{"credentials": slot.Credentials, "config": slot.Config})
	write := func(name string, raw []byte) {
		if err := os.WriteFile(filepath.Join(dir, name), raw, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	write("em-abc123.meta.json", []byte(`{"id":"em-abc123","label":"导入账号","email":"i@b.com","userId":"uid-imp","provider":"builtin:zai","capturedAt":1700000000000}`))
	write("em-abc123.snap.json", snapRaw)
	// Broken pair: meta without a valid snap.
	write("broken.meta.json", []byte(`{"id":"broken","label":"坏的"}`))
	write("broken.snap.json", []byte(`{"credentials":"not json","config":"{}"}`))

	imported, skipped, err := m.Import("zcode", source)
	if err != nil {
		t.Fatal(err)
	}
	if len(imported) != 1 || imported[0] != "em-abc123" {
		t.Fatalf("imported: %v", imported)
	}
	if len(skipped) != 1 || skipped[0].ID != "broken" {
		t.Fatalf("skipped: %+v", skipped)
	}
	acc, err := m.loadAccount("zcode", "em-abc123")
	if err != nil {
		t.Fatal(err)
	}
	if acc.Credentials != slot.Credentials || acc.Config != slot.Config || acc.Label != "导入账号" || acc.Status != StatusActive {
		t.Fatalf("imported account: %+v", acc)
	}
	// Second import skips the existing account.
	imported, skipped, err = m.Import("zcode", source)
	if err != nil || len(imported) != 0 {
		t.Fatalf("re-import: %v %v", imported, err)
	}
}

