func TestZcodeQuotaBillingNormalize(t *testing.T) {
	current := map[string]any{
		"data": map[string]any{
			"plans": []any{
				map[string]any{"plan_id": "pro-monthly", "status": "active"},
			},
		},
	}
	balance := map[string]any{
		"data": map[string]any{
			"balances": []any{
				map[string]any{"show_name": "GLM-4.6", "total_units": 1000000.0, "used_units": 950000.0,
					"period_end": "2026-11-01T00:00:00Z"},
				map[string]any{"show_name": "GLM-4.5-Air", "total_units": 2000000.0, "used_units": 10.0},
			},
		},
	}
	quota := normalizeZcodeQuota(current, balance)
	if quota.LevelName != "Pro" {
		t.Fatalf("plan tier: %q", quota.LevelName)
	}
	if len(quota.Limits) != 2 {
		t.Fatalf("limits: %+v", quota.Limits)
	}
	first := quota.Limits[0]
	if first.Name != "GLM-4.6" || first.Used != 950000 || first.Limit != 1000000 || first.ResetAt != "2026-11-01T00:00:00Z" {
		t.Fatalf("first window: %+v", first)
	}
	// The 95% window reads exhausted, the fresh one does not.
	if got := ExhaustedWindows(quota, 0.95); len(got) != 1 || got[0].Name != "GLM-4.6" {
		t.Fatalf("exhausted: %+v", got)
	}
}

