func TestZcodeMonitorNormalize(t *testing.T) {
	body := map[string]any{
		"code": 200,
		"data": map[string]any{
			"level": "pro",
			"limits": []any{
				map[string]any{"type": "TIME_LIMIT", "usage": 1000.0, "currentValue": 20.0, "nextResetTime": 1798761600000.0},
				map[string]any{"type": "TOKENS_LIMIT", "usage": 5000000.0, "currentValue": 4900000.0, "nextResetTime": "2026-11-01T00:00:00Z"},
			},
		},
	}
	quota := normalizeZcodeMonitor(body)
	if quota.LevelName != "Pro" {
		t.Fatalf("level: %q", quota.LevelName)
	}
	// TOKENS_LIMIT sorts before TIME_LIMIT.
	if len(quota.Limits) != 2 || quota.Limits[0].Name != "Token 用量" || quota.Limits[1].Name != "MCP 用量" {
		t.Fatalf("limits: %+v", quota.Limits)
	}
	if quota.Limits[0].Auxiliary || !quota.Limits[1].Auxiliary {
		t.Fatalf("auxiliary flags: %+v", quota.Limits)
	}
	if quota.Limits[1].ResetAt != "2027-01-01T00:00:00Z" {
		t.Fatalf("epoch reset time: %q", quota.Limits[1].ResetAt)
	}
	if got := ExhaustedWindows(quota, 0.95); len(got) != 1 || got[0].Name != "Token 用量" {
		t.Fatalf("exhausted: %+v", got)
	}
	// Even with MCP 用量 over 100%, the account stays available: only the AI
	// token window gates exhaustion.
	quota.Limits[1].Used = 1010
	if got := ExhaustedWindows(quota, 0.95); len(got) != 1 || got[0].Name != "Token 用量" {
		t.Fatalf("exhausted with MCP over 100%%: %+v", got)
	}
	quota.Limits[0].Used = 0
	if got := ExhaustedWindows(quota, 0.95); len(got) != 0 {
		t.Fatalf("auxiliary-only exhaustion must not trigger: %+v", got)
	}
}

// TOKENS_LIMIT rows on Lite accounts carry no usage/currentValue at all —
// only percentage + nextResetTime (epoch millis); the window must synthesize
// from percentage or the UI shows 暂未提供 while zcode-switcher shows numbers.
func TestZcodeMonitorNormalizePercentageOnly(t *testing.T) {
	body := map[string]any{
		"code": 200,
		"data": map[string]any{
			"level": "lite",
			"limits": []any{
				map[string]any{
					"type": "TIME_LIMIT", "usage": 100.0, "currentValue": 43.0,
					"percentage": 43.0, "remaining": 57.0,
					"nextResetTime": 1792688249981.0, "number": 1.0, "unit": 5.0,
				},
				map[string]any{
					"type": "TOKENS_LIMIT", "percentage": 79.0,
					"nextResetTime": 1792589064319.0, "number": 5.0, "unit": 3.0,
				},
			},
		},
	}
	quota := normalizeZcodeMonitor(body)
	if len(quota.Limits) != 2 {
		t.Fatalf("limits: %+v", quota.Limits)
	}
	token, mcp := quota.Limits[0], quota.Limits[1]
	if token.Name != "Token 用量" || token.Limit != 1000 || token.Used != 790 {
		t.Fatalf("token window: %+v", token)
	}
	if token.ResetAt == "" || token.Auxiliary {
		t.Fatalf("token window flags: %+v", token)
	}
	if mcp.Name != "MCP 用量" || mcp.Used != 43 || mcp.Limit != 100 {
		t.Fatalf("mcp keeps absolute numbers: %+v", mcp)
	}
	// The synthesized window must gate exhaustion like a real one: 79% is
	// below the threshold, 99% trips it.
	if got := ExhaustedWindows(quota, 0.95); len(got) != 0 {
		t.Fatalf("79%% must not be exhausted: %+v", got)
	}
	quota.Limits[0].Used = 990
	if got := ExhaustedWindows(quota, 0.95); len(got) != 1 || got[0].Name != "Token 用量" {
		t.Fatalf("exhausted at 99%%: %+v", got)
	}
}

func TestZcodeQueryQuotaFlow(t *testing.T) {
	var billingHits, monitorHits int
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		switch {
		case strings.HasSuffix(r.URL.Path, "/billing/current"):
			billingHits++
			if r.Header.Get("authorization") != "Bearer good-token-1234567890123" {
				w.WriteHeader(http.StatusUnauthorized)
				_, _ = w.Write([]byte(`{"message":"bad token"}`))
				return
			}
			if v := r.URL.Query().Get("app_version"); v != zcodeClientAppVersion {
				t.Errorf("app_version missing: %q", r.URL.RawQuery)
			}
			_, _ = w.Write([]byte(`{"data":{"plans":[{"plan_id":"max-monthly","status":"active"}]}}`))
		case strings.HasSuffix(r.URL.Path, "/billing/balance"):
			_, _ = w.Write([]byte(`{"data":{"balances":[{"show_name":"GLM","total_units":100,"used_units":10}]}}`))
		default:
			monitorHits++
			// The monitor endpoint takes the bare token, no Bearer prefix.
			if r.Header.Get("authorization") == "Bearer good-token-1234567890123" {
				t.Error("monitor must not get a Bearer prefix")
			}
			_, _ = w.Write([]byte(`{"code":200,"data":{"level":"lite","limits":[]}}`))
		}
	}))
	defer server.Close()
	restoreCurrent, restoreBalance := zcodeBillingCurrentURL, zcodeBillingBalanceURL
	restoreMonitor := zcodeMonitorURLs
	zcodeBillingCurrentURL = server.URL + "/api/v1/zcode-plan/billing/current"
	zcodeBillingBalanceURL = server.URL + "/api/v1/zcode-plan/billing/balance"
	zcodeMonitorURLs = []string{server.URL + "/api/monitor/usage/quota/limit"}
	t.Cleanup(func() {
		zcodeBillingCurrentURL, zcodeBillingBalanceURL, zcodeMonitorURLs = restoreCurrent, restoreBalance, restoreMonitor
	})

	// First token 401s, the second succeeds: no monitor fallback.
	quota, err := queryZcodeQuota(context.Background(), []string{"bad-token-123456789012345", "good-token-1234567890123"})
	if err != nil {
		t.Fatal(err)
	}
	if quota.LevelName != "Max" || len(quota.Limits) != 1 || quota.Limits[0].Limit != 100 {
		t.Fatalf("quota: %+v", quota)
	}
	if monitorHits != 0 {
		t.Fatalf("monitor must not fire when billing works: %d", monitorHits)
	}
}

